//! Writes every generated file under `docs/reference`.

use std::fs;
use std::path::Path;

use anyhow::{Context, Result};

use crate::{cli_docs, ipc_docs};

/// First line of every generated file. JSON carries it as `$comment`.
pub const HEADER: &str = "Generated by `cargo run -p xtask -- docs`. Do not edit.";

pub fn generate(root: &Path) -> Result<()> {
    let reference = root.join("docs/reference");
    let man = reference.join("man");
    fs::create_dir_all(&man).context("cannot create docs/reference/man")?;

    write(&reference.join("cli.md"), &cli_docs::markdown())?;
    write_man_pages(&man)?;
    write(&reference.join("ipc.md"), &ipc_docs::markdown())?;
    write(
        &reference.join("ipc.schema.json"),
        &ipc_docs::json_schema()?,
    )?;
    println!("wrote {}", reference.display());
    Ok(())
}

fn write_man_pages(dir: &Path) -> Result<()> {
    // Drop stale pages, so a removed subcommand leaves no file behind.
    for entry in fs::read_dir(dir)? {
        let path = entry?.path();
        if path.extension().is_some_and(|e| e == "1") {
            fs::remove_file(&path)?;
        }
    }
    for (name, page) in cli_docs::man_pages()? {
        write(&dir.join(format!("{name}.1")), &page)?;
    }
    Ok(())
}

fn write(path: &Path, body: &str) -> Result<()> {
    fs::write(path, body).with_context(|| format!("cannot write {}", path.display()))
}
